form.sem_template:
{% set html = {"&": "&amp;", "<": "&lt;", ">": "&gt;"} %}
{% set lead = "<p><strong>" ~ (bf_titre | replace(html)) ~ "</strong></p>" ~ (bf_chapeau | default("") ? "<p><em>" ~ (bf_chapeau | replace(html)) ~ "</em></p>" : "") %}
{
  "@context": "https://www.w3.org/ns/activitystreams",
  "type": "Note",
  {% if bf_avertissement | default("") %}
  "summary": {{ bf_avertissement | json_encode }},
  "sensitive": true,
  {% endif %}
  "preview": {{ bf_chapeau | default("") | json_encode }},
  "content": {{ (lead ~ format(bf_description | default(""))) | json_encode }},
  "published": {{ created_at | date("c") | json_encode }},
  "updated": {{ updated_at | default(created_at) | date("c") | json_encode }},
  "attachment": [
    {% if imagebf_image | default("") %}
    {
      "type": "Image",
      "url": {{ fileUrl(imagebf_image) | json_encode }}
    }
    {% endif %}
  ]
}

form.sem_reverse_template:
{% set html = {"&": "&amp;", "<": "&lt;", ">": "&gt;"} %}
{% set text = {"&amp;": "&", "&lt;": "<", "&gt;": ">"} %}
{% set head = content | default("") | split("</strong></p>", 2) %}
{% set leadTitle = head | length == 2 and head | first starts with "<p><strong>" ? head | first | slice(11) | replace(text) : "" %}
{% set title = name | default("") ?: leadTitle %}
{% set lead = "<p><strong>" ~ (title | replace(html)) ~ "</strong></p>" ~ (preview | default("") ? "<p><em>" ~ (preview | replace(html)) ~ "</em></p>" : "") %}
{
  "bf_titre": {{ title | json_encode }},
  "bf_chapeau": {{ preview | default("") | json_encode }},
  "bf_avertissement": {{ summary | default("") | json_encode }},
  "bf_description": {{ markdown(content | default("") | replace({(lead): ""})) | json_encode }},
  "imagebf_image": {{ (attachment | default([]) | first).url | default("") | json_encode }},
  "created_at": {{ (published | default("") ? published | date("Y-m-d H:i:s") : null) | json_encode }},
  "updated_at": {{ ((updated | default("") ?: published | default("")) ? (updated | default("") ?: published) | date("Y-m-d H:i:s") : null) | json_encode }}
}

